const msg = $input.first().json.message;
if (!msg) return [];
const chatId = String(msg.chat.id);
const allowedChatId = ''; // OPSIONAL: Isi Chat ID Telegram Anda untuk membatasi akses
if (allowedChatId && chatId !== allowedChatId) return [];

const photos = Array.isArray(msg.photo) ? msg.photo : [];
if (photos.length === 0) {
  return [{ json: { mode: 'help', chatId } }];
}

const bestPhoto = photos[photos.length - 1];
return [{
  json: {
    mode: 'affiliate',
    chatId,
    fileId: bestPhoto.file_id,
    userNotes: (msg.caption || '').trim(),
    jobId: `aff_${Date.now()}`
  }
}];

const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const meta = $('Check Photo Upload').item.json;
const binaryInfo = $input.first().binary?.data || {};
return [{
  json: {
    jobId: meta.jobId,
    chatId: meta.chatId,
    userNotes: meta.userNotes,
    productImageBase64: buffer.toString('base64'),
    productImageMimeType: binaryInfo.mimeType || 'image/jpeg'
  }
}];

